import{_ as p,a0 as a,w as l,s as r,ao as d,I as i,x as t,a1 as n,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"如何在 winSCP 中使用 sudo | LCTT x X-CMD","titleTemplate":false,"description":"如何在 winSCP 中使用 sudo | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 winSCP 中使用 sudo | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 winSCP 中使用 sudo | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190301 How to use sudo access in winSCP","title":"如何在 winSCP 中使用 sudo","tag":"201903","desc":""},"relativePath":"201903/20190301 How to use sudo access in winSCP.md","filePath":"[post].md"}'),u={name:"201903/20190301 How to use sudo access in winSCP.md"};function w(m,s,C,c,f,k){const e=a("Link");return l(),r("div",null,[s[15]||(s[15]=d(`<h1 id="如何在-winscp-中使用-sudo" tabindex="-1">如何在 winSCP 中使用 sudo <a class="header-anchor" href="#如何在-winscp-中使用-sudo" aria-label="Permalink to “如何在 winSCP 中使用 sudo”">​</a></h1><blockquote><p>用截图了解如何在 winSCP 中使用 sudo。</p></blockquote><p><img src="https://i2.wp.com/kerneltalks.com/wp-content/uploads/2019/03/How-to-use-sudo-access-in-winSCP.png?ssl=1" alt="How to use sudo access in winSCP"></p><p><em>sudo access in winSCP</em></p><p>首先你需要检查你尝试使用 winSCP 连接的 sftp 服务器的二进制文件的位置。</p><p>你可以使用以下命令检查 SFTP 服务器二进制文件位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kerneltalks ~]# cat /etc/ssh/sshd_config |grep -i sftp-server</span></span>
<span class="line"><span>Subsystem sftp  /usr/libexec/openssh/sftp-server</span></span></code></pre></div><p>你可以看到 sftp 服务器的二进制文件位于 <code>/usr/libexec/openssh/sftp-server</code>。</p><p>打开 winSCP 并单击“高级”按钮打开高级设置。</p><p><img src="https://i0.wp.com/kerneltalks.com/wp-content/uploads/2019/03/winscp-advanced-settings.jpg?ssl=1" alt="winSCP advance settings"></p><p><em>winSCP 高级设置</em></p><p>它将打开如下高级设置窗口。在左侧面板上选择“Environment”下的 “SFTP”。你会在右侧看到选项。</p><p>现在，使用命令 <code>sudo su -c</code> 在这里添加 SFTP 服务器值，如下截图所示：</p><p><img src="https://i1.wp.com/kerneltalks.com/wp-content/uploads/2019/03/SFTP-server-setting-in-winSCP.jpg?ssl=1" alt="SFTP server setting in winSCP"></p><p><em>winSCP 中的 SFTP 服务器设置</em></p><p>所以我们在设置中添加了 <code>sudo su -c /usr/libexec/openssh/sftp-server</code>。单击“Ok”并像平常一样连接到服务器。</p><p>连接之后，你将可以从你以前需要 sudo 权限的目录传输文件了。</p><p>完成了！你已经使用 winSCP 使用 sudo 登录服务器了。</p><hr>`,19)),i("p",null,[s[1]||(s[1]=t("via: ",-1)),n(e,{href:"https://kerneltalks.com/tools/how-to-use-sudo-access-in-winscp/"},{default:o(()=>[...s[0]||(s[0]=[t("https://kerneltalks.com/tools/how-to-use-sudo-access-in-winscp/",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=t("作者：",-1)),n(e,{href:"https://kerneltalks.com"},{default:o(()=>[...s[2]||(s[2]=[t("kerneltalks",-1)])]),_:1}),s[7]||(s[7]=t(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[3]||(s[3]=[t("lujun9972",-1)])]),_:1}),s[8]||(s[8]=t(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:o(()=>[...s[4]||(s[4]=[t("geekpi",-1)])]),_:1}),s[9]||(s[9]=t(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...s[5]||(s[5]=[t("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[10]||(s[10]=[t("LCTT",-1)])]),_:1}),s[13]||(s[13]=t(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:o(()=>[...s[11]||(s[11]=[t("Linux中国",-1)])]),_:1}),s[14]||(s[14]=t(" 荣誉推出",-1))])])}const T=p(u,[["render",w]]);export{g as __pageData,T as default};
